from typing import List, Dict, Tuple

def compress_list(input_list: List[int]) -> Tuple[List[int], Dict[int, int]]:
    if not input_list:
        return [], {}

    compressed_list = []
    counts_dict = {}

    current_count = 1
    current_val = input_list[0]

    for i in range(1, len(input_list)):
        if input_list[i] == current_val:
            current_count += 1
        else:
            compressed_list.append(current_val)
            counts_dict[current_val] = current_count
            current_val = input_list[i]
            current_count = 1

    # Append the last group
    compressed_list.append(current_val)
    counts_dict[current_val] = current_count

    return compressed_list, counts_dict
```

