def unique_chars(input_str: str) -> str:
    """
    Returns a new string with unique characters from input_str, preserving order.
    """
    seen = set()
    result = []
    for char in input_str:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)
```

