import heapq

def find_k_largest_elements(arr, k):
    if k == 0:
        return []
    if k >= len(arr):
        return sorted(arr, reverse=True)

    # Use a min-heap of size k to keep track of the k largest elements
    heap = []
    for i in range(len(arr)):
        if len(heap) < k:
            heapq.heappush(heap, arr[i])
        else:
            if arr[i] > heap[0]:
                heapq.heapreplace(heap, arr[i])

    # Return the k largest elements in descending order
    return sorted(heap, reverse=True)

