def find_longest_common_prefix(words):
    if not words:
        return ""

    # Start with the first word as the reference
    prefix = words[0]

    # Iterate through the rest of the words
    for word in words[1:]:
        # Shorten prefix until it matches the start of the current word
        while not word.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix
```

