def fib(n: int) -> int:
    """Return the nth Fibonacci number using memoized recursion."""
    memo = {0: 0, 1: 1}

    def helper(k: int) -> int:
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]

    return helper(n)
```

