class InventoryManager:
    def __init__(self):
        self._inventory = {}

    def add_item(self, name: str, quantity: int) -> None:
        """Add a new item or increase existing quantity."""
        if name in self._inventory:
            self._inventory[name] += quantity
        else:
            self._inventory[name] = quantity

    def update_quantity(self, name: str, quantity: int) -> None:
        """Set the quantity of an existing item. Raises ValueError if not found."""
        if name not in self._inventory:
            raise ValueError(f"Item '{name}' not found in inventory.")
        self._inventory[name] = quantity

    def remove_item(self, name: str) -> None:
        """Remove an item from the inventory. Raises ValueError if not found."""
        if name not in self._inventory:
            raise ValueError(f"Item '{name}' not found in inventory.")
        del self._inventory[name]

    def display_inventory(self) -> None:
        """Print the current inventory in the specified format."""
        if not self._inventory:
            print("Inventory is empty.")
            return
        print("Current Inventory:")
        for item, qty in self._inventory.items():
            print(f"Item: {item}, Quantity: {qty}")
