def remove_duplicates_and_sort_desc(numbers):
    # Use a list to track seen numbers and build unique list
    seen = []
    for num in numbers:
        if num not in seen:
            seen.append(num)

    # Manual bubble sort in descending order
    n = len(seen)
    for i in range(n):
        for j in range(0, n - 1 - i):
            if seen[j] < seen[j + 1]:
                seen[j], seen[j + 1] = seen[j + 1], seen[j]

    return seen

