import heapq
from typing import List

def running_median(nums: List[int]) -> List[float]:
    # Two heaps: max_heap for the left half, min_heap for the right half
    max_heap: List[int] = []  # stores negative values to simulate max heap
    min_heap: List[int] = []
    result: List[float] = []

    for num in nums:
        # Maintain the invariant: len(max_heap) == len(min_heap) or len(max_heap) == len(min_heap) + 1
        if not max_heap and not min_heap:
            heapq.heappush(max_heap, -num)
        elif (len(max_heap) == len(min_heap)) or (len(max_heap) == len(min_heap) + 1):
            if num > -max_heap[0]:
                heapq.heappush(min_heap, num)
            else:
                heapq.heappush(max_heap, -num)
        else:
            if num < -max_heap[0]:
                heapq.heappush(max_heap, -num)
            else:
                heapq.heappush(min_heap, num)

        # Rebalance if necessary
        if len(max_heap) > len(min_heap) + 1:
            heapq.heappush(min_heap, -heapq.heappop(max_heap))
        elif len(min_heap) > len(max_heap):
            heapq.heappush(max_heap, -heapq.heappop(min_heap))

        # Calculate median
        if len(max_heap) == len(min_heap):
            median = (-max_heap[0] + min_heap[0]) / 2.0
        else:
            median = -max_heap[0]
        result.append(median)

    return result

# Example usage
nums = [2, 1, 5, 7, 2, 0, 5]
print(running_median(nums))
