def exponentiate_matrix(matrix, p=2):
    """
    Raise each element of a 2D matrix to the power of p using only multiplication and loops.
    """
    m = len(matrix)
    n = len(matrix[0])
    result = [[0] * n for _ in range(m)]

    for i in range(m):
        for j in range(n):
            val = matrix[i][j]
            power = 1
            if val == 0:
                power = 0
            elif val == 1:
                power = 1
            else:
                for _ in range(p):
                    power *= val
            result[i][j] = power

    return result
```

