def format_date(date_str: str) -> str:
    try:
        year, month, day = map(int, date_str.split("-"))
        if not (1 <= month <= 12) or not (1 <= day <= 31):
            return "Error: Invalid date format. Please use 'YYYY-MM-DD'."
        if month in [4, 6, 9, 11]:
            if day > 30:
                return "Error: Invalid date format. Please use 'YYYY-MM-DD'."
