            max_day = 29 if is_leap else 28
            if day > max_day:
                return "Error: Invalid date format. Please use 'YYYY-MM-DD'."
        return f"{day:02d}/{month:02d}/{year:04d}"
    except (ValueError, AttributeError):
        return "Error: Invalid date format. Please use 'YYYY-MM-DD'."
