def find_longest_palindrome(s: str) -> str:
    if not s:
        return ""

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> tuple:
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1  # Valid range [left+1, right-1]

    for i in range(len(s)):
        # Odd length
        l, r = expand_around_center(i, i)
        if r - l + 1 > end - start:
            start, end = l, r

        # Even length
        l, r = expand_around_center(i, i + 1)
        if r - l + 1 > end - start:
            start, end = l, r

    return s[start:end+1]
```

