from typing import List, Union

def elementwise_product(list1: List[Union[int, List]], list2: List[Union[int, List]]) -> List[Union[int, List]]:
    def multiply(a, b):
        if isinstance(a, int) and isinstance(b, int):
            return a * b
        elif isinstance(a, list) and isinstance(b, list):
            return elementwise_product(a, b)
        else:
            raise TypeError("Mismatched types during recursion")

