import math

def get_nth_prime(n: int) -> int:
    """Return the nth prime number (1-indexed)."""
    if n <= 0:
        raise ValueError("n must be >= 1")

    count = 0
    candidate = 2

    while count < n:
        is_prime = True
        limit = int(math.isqrt(candidate))
        for d in range(2, limit + 1):
            if candidate % d == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
            if count == n:
                return candidate
        candidate += 1

