        raise ValueError("Dimension i must be between 0 and 2.")
    if not (2 <= side <= 100):
        raise ValueError("Side length must be between 2 and 100.")

    # Check if original side at dimension i is prime
    original_side = cube[i]
    if not is_prime(original_side):
        raise ValueError(f"Original side length at dimension {i} ({original_side}) must be a prime number.")

    # Validate new side is not prime
    if is_prime(side):
        raise ValueError(f"New side length ({side}) must not be a prime number.")

    # Create new cube with modified side
    new_cube = list(cube)
    new_cube[i] = side

    return new_cube

