```python
def sum_primes_less_than(n: int) -> int:
    """
    Compute the sum of all prime numbers less than n using the Sieve of Eratosthenes.
    Time Complexity: O(n log log n)
    Space Complexity: O(n)
    """
    if n <= 2:
        return 0

    # Sieve array: True means prime, False means composite
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False

    return sum(i for i in range(2, n) if is_prime[i])
```

