def process_track_data(track_data, classification_map, interaction_map):
    """
    Processes track_data string and returns a dictionary mapping classification/interaction
    to maximum score for sub-tracks with length > 10.
    """
    results = {}

    # Split by semicolon
    parts = track_data.split(';')

    for part in parts:
        # Split by pipe
        segments = part.split('|')

        if len(segments) < 2:
            continue

        track_name, score_str = segments[0], segments[1]

        # Validate score
        try:
            score = float(score_str)
        except ValueError:
            continue

        # Check length constraint
        if len(track_name) <= 10:
            continue

        # Split track name by comma
        sub_tracks = track_name.split(',')

        for sub in sub_tracks:
            if len(sub) <= 10:
                continue

            # Determine classification
            if "ConCavity" in sub:
                cls = "pocket"
            elif "JSD_conservation" in sub:
                cls = "conservation"
            elif "WholeGene_NatVar" in sub:
                cls = "mutfreq"
            elif sub.startswith("PF") and sub.endswith(":complete"):
                cls = classification_map.get(sub, "domain")
            elif sub.startswith("Homology_binding") or sub.startswith("PF"):
                cls = interaction_map.get(sub, "sm")
            else:
                continue  # Skip if no rule matches

            # Update max score
            if cls not in results or score > results[cls]:
                results[cls] = score

    return results
