def process_track_data(track_data, classification_map, interaction_map):
    """
    Processes track data and returns a dictionary mapping classification/interaction to max score.
    Only considers sub-tracks with length > 10.
    """
    results = {}

    # Split by semicolon to get track entries
    tracks = track_data.split(';')

    for track in tracks:
        # Split by pipe to get name and score
        parts = track.split('|')
        if len(parts) != 2:
            continue

        name, score_str = parts
        score = float(score_str)

        # Check length constraint
        if len(name) <= 10:
            continue

        # Split name by comma to get sub-tracks
        sub_tracks = name.split(',')

        for sub_track in sub_tracks:
            # Determine classification based on rules
            if "ConCavity" in sub_track:
                classification = "pocket"
            elif "JSD_conservation" in sub_track:
                classification = "conservation"
            elif "WholeGene_NatVar" in sub_track:
                classification = "mutfreq"
            elif sub_track.startswith("PF") and sub_track.endswith(":complete"):
                classification = classification_map.get(sub_track, "domain")
            elif sub_track.startswith("Homology_binding") or sub_track.startswith("PF"):
                classification = interaction_map.get(sub_track, "sm")
            else:
                continue  # Skip if no classification rule matches

            # Update max score for this classification
            if classification in results:
                results[classification] = max(results[classification], score)
            else:
                results[classification] = score

    return results
```

