def power_sum(numbers, power=2):
    """
    Calculate the sum of each number in the list raised to the given power
    without using built-in exponentiation functions.
    """
    def raise_to_power(base, exp):
        if exp == 0:
            return 1
        if exp == 1:
            return base
        if base < 0 and exp % 2 == 0:
            return raise_to_power(-base, exp)
        result = 1
        for _ in range(exp):
            result *= base
        return result

    total = 0
    for num in numbers:
        total += raise_to_power(num, power)
    return total
```

