import csv
import sys

def calculate_total_salary(filename):
    try:
        with open(filename, 'r', newline='') as f:
            reader = csv.DictReader(f)

            # Check if required columns exist
            if not reader.fieldnames:
                print("Error: CSV file does not contain any columns.")
                return

            required_columns = {'employee_id', 'name', 'position', 'salary', 'department'}
            if not required_columns.issubset(set(reader.fieldnames)):
                missing = required_columns - set(reader.fieldnames)
                print(f"Error: CSV file is missing required columns: {missing}")
                return

            total_salary = 0.0
            valid_rows = 0

            for row in reader:
                try:
                    salary = float(row['salary'])
                    if salary < 0:
                        print(f"Error: Invalid salary value ({salary}) found for employee {row['employee_id']}. Skipping.")
                        continue
                    total_salary += salary
                    valid_rows += 1
                except ValueError:
                    print(f"Error: Invalid salary value '{row['salary']}' found for employee {row['employee_id']}. Skipping.")
                    continue

            if valid_rows == 0:
                print("Error: No valid salary values found in the file.")
                return

            formatted_total = f"${total_salary:,.2f}"
            print(f"Total salary expenditure: {formatted_total}")

    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
    except Exception as e:
        print(f"Error: An unexpected error occurred: {e}")

if __name__ == "__main__":
