def is_valid(s: str) -> bool:
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return False
            if stack[-1] == pairs[char]:
                stack.pop()
            else:
                return False
        else:
            return False  # Should not happen given constraints

    return len(stack) == 0
```

