def decimal_to_binary(n: int) -> str:
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("Input must be an integer")

    if n == 0:
        return "0"

    sign = "-" if n < 0 else ""
    n = abs(n)

    binary_digits = []
    while n > 0:
        binary_digits.append(str(n % 2))
        n //= 2

    return sign + "".join(reversed(binary_digits))
```

