def hex2rgb(hex_color: str) -> tuple[int, int, int] | None:
    """Convert a hex color code to an RGB tuple. Returns None if invalid."""
    if not isinstance(hex_color, str) or not hex_color.startswith("#"):
        return None
    hex_color = hex_color[1:]  # Remove '#'
    if len(hex_color) != 6:
        return None
    try:
        r = int(hex_color[0:2], 16)
        g = int(hex_color[2:4], 16)
        b = int(hex_color[4:6], 16)
        return (r, g, b)
    except ValueError:
        return None
