from typing import Dict, List, Any

class Employee:
    def __init__(self, name: str, id_number: str, salary: int):
        self.name = name
        self.id_number = id_number
        self.salary = salary

def serialize_employee(
    emp: Employee,
    fields: List[str],
    include_sensitive_info: bool = False
) -> Dict[str, Any]:
    """
    Serializes specified fields from an Employee object into a dictionary.

    If include_sensitive_info is False, fields marked as sensitive (e.g., 'salary') are excluded.
    """
    sensitive_fields = {'salary'}
    selected_fields = set(fields)

    if not include_sensitive_info:
        selected_fields -= sensitive_fields

