**Time Complexity:** O(n) on average  
**Space Complexity:** O(1) (in-place partitioning)

```python
def find_kth_smallest(nums, k):
    """
    Returns the k-th smallest element in an unsorted list using a selection algorithm.
    Average time complexity: O(n)
    """
    n = len(nums)
    if k < 1 or k > n:
        raise ValueError("k must be between 1 and len(nums)")

    # Quickselect: partition around a pivot and recurse on the side containing the k-th element
    def partition(arr, l, r):
        # Choose middle element as pivot to avoid worst-case on sorted data
        pivot_idx = (l + r) // 2
        pivot = arr[pivot_idx]
        arr[pivot_idx], arr[r] = arr[r], arr[pivot_idx]

        i = l - 1
        for j in range(l, r):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[r] = arr[r], arr[i + 1]
        return i + 1

    def quickselect(arr, k, l, r):
        if l == r:
            return arr[l]
        pivot_idx = partition(arr, l, r)
        if k == pivot_idx - l + 1:
            return arr[pivot_idx]
        elif k < pivot_idx - l + 1:
            return quickselect(arr, k, l, pivot_idx - 1)
        else:
            return quickselect(arr, k - (pivot_idx - l + 1), pivot_idx + 1, r)

    return quickselect(nums, k, 0, n - 1)
```

