from collections import Counter, defaultdict

def can_split_text(text: str, word_count: dict) -> bool:
    """
    Determine if text can be split into words from word_count without exceeding frequencies.
    """
    word_freq = Counter(text)
    available = defaultdict(int)
    for w, f in word_count.items():
        available[w] = f

    def dfs(start_idx: int) -> bool:
        if start_idx == len(text):
            return True

        for i in range(start_idx + 1, len(text) + 1):
            candidate = text[start_idx:i]
            if candidate not in available:
                continue

            # Check if we have enough remaining count
            if available[candidate] > 0:
                available[candidate] -= 1
                if dfs(i):
                    return True
                available[candidate] += 1

        return False

    return dfs(0)


