```python
def longest_palindrome_substring(s: str) -> str:
    n = len(s)
    if n == 0:
        return ""

    # dp[i][j] is True if s[i:j+1] is a palindrome
    dp = [[False] * n for _ in range(n)]

    # All single characters are palindromes
    for i in range(n):
        dp[i][i] = True

    # All length-2 substrings
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True

    # Fill DP for lengths 3 to n
    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j] and dp[i + 1][j - 1]:
                dp[i][j] = True

    max_len = 0
    start = 0
    for i in range(n):
        for j in range(i, n):
            if dp[i][j]:
                if j - i + 1 > max_len:
                    max_len = j - i + 1
                    start = i

    return s[start:start + max_len]


# Example usage:
# s = "babad"
# print(longest_palindrome_substring(s))  # Output: "bab" or "aba"
