        start = 2

    # Sieve of Eratosthenes up to end
    is_prime = [True] * (end + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(end ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, end + 1, i):
                is_prime[j] = False

    # Collect primes in range
    primes = []
    for num in range(start, end + 1):
        if is_prime[num]:
            primes.append(num)

    return primes
```

