def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries. If a key exists in both and the values are dicts,
    they are merged recursively. Otherwise, dict2's value overwrites dict1's.
    """
    result = dict1.copy()

    for key, value in dict2.items():
        if key in result:
            if isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = merge_dictionaries(result[key], value)
            else:
                result[key] = value
        else:
            result[key] = value

    return result
```

