def factorize(n: int) -> list[int]:
    if n == 1:
        return []

    factors = []
    d = 2
    temp = n

    while d * d <= temp:
        if temp % d == 0:
            while temp % d == 0:
                factors.append(d)
                temp //= d
        d += 1

    if temp > 1:
        factors.append(temp)

    return factors
