class EmployeeManager:
    def __init__(self):
        self._employees = {}
        self._next_id = 1

    def create(self, name, position):
        if self._next_id in self._employees:
            raise ValueError(f"ID {self._next_id} already exists.")
        employee = {
            'id': self._next_id,
            'name': name,
            'position': position
        }
        self._employees[self._next_id] = employee
        self._next_id += 1
        return employee

    def read(self, employee_id=None):
        if employee_id is None:
            return dict(self._employees)
        if employee_id not in self._employees:
            return f"Employee with ID {employee_id} not found."
        return self._employees[employee_id]

    def update(self, employee_id, name=None, position=None):
        if employee_id not in self._employees:
            return f"Employee with ID {employee_id} not found."
        if name is not None:
            self._employees[employee_id]['name'] = name
        if position is not None:
            self._employees[employee_id]['position'] = position
        return self._employees[employee_id]

    def delete(self, employee_id):
        if employee_id not in self._employees:
            return f"Employee with ID {employee_id} not found."
        del self._employees[employee_id]
        return f"Employee with ID {employee_id} deleted."
