def should_switch_service(service_type: str, industry_sector: str, switch_criteria: dict, years: dict) -> bool:
    # Check service_type in switch_criteria
    if service_type not in switch_criteria:
        return True  # Unknown service type -> switch

    allowed_sectors = switch_criteria[service_type]

    # If allowed_sectors is None, switch for all sectors
    if allowed_sectors is None:
        return True

    # If allowed_sectors is a list, check if current sector is in the list
    if industry_sector not in allowed_sectors:
        return False

    # Check years
    base_year = years.get("base_year")
    current_year = years.get("current_year")

    if base_year is not None and current_year is not None and base_year == current_year:
        return False

    # Check maintenance_window
    if "maintenance_window" in years:
        for start, end in years["maintenance_window"]:
            if start <= current_year <= end:
                return False

    return True
