def merge_sorted_lists(list_a, list_b):
    merged_list = []
    i, j = 0, 0

    # Filter out -1 and merge
    while i < len(list_a) and j < len(list_b):
        if list_a[i] == -1:
            i += 1
            continue
        if list_b[j] == -1:
            j += 1
            continue

        if list_a[i] <= list_b[j]:
            merged_list.append(list_a[i])
            i += 1
        else:
            merged_list.append(list_b[j])
            j += 1

    # Append remaining elements from list_a
    while i < len(list_a):
        if list_a[i] != -1:
            merged_list.append(list_a[i])
        i += 1

    # Append remaining elements from list_b
    while j < len(list_b):
