def find_longest_palindrome(text: str) -> str:
    if not text:
        return ""

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> tuple:
        while left >= 0 and right < len(text) and text[left] == text[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(len(text)):
        # Odd length palindromes
        l1, r1 = expand_around_center(i, i)
        # Even length palindromes
        l2, r2 = expand_around_center(i, i + 1)

        # Update if current palindrome is longer, or same length but earlier
        if (r1 - l1) > (end - start) or ((r1 - l1) == (end - start) and l1 < start):
            start, end = l1, r1
        if (r2 - l2) > (end - start) or ((r2 - l2) == (end - start) and l2 < start):
            start, end = l2, r2

    return text[start:end + 1]
```

