def is_valid_ipv4(ip: str) -> bool:
    parts = ip.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Must contain only digits
        if not part.isdigit():
            return False

        # No leading zeros unless the number is "0"
        if len(part) > 1 and part[0] == '0':
            return False

        # Must be between 0 and 255
        if not (0 <= int(part) <= 255):
            return False

    return True
