import json

def calculate_total_value(filename: str) -> None:
    try:
        with open(filename, 'r') as f:
            data = json.load(f)
    except FileNotFoundError:
        print(f"Error: File '{filename}' not found.")
        return
    except json.JSONDecodeError:
        print("Error: Invalid JSON format.")
        return

    total_value = 0.0

    if not isinstance(data, list):
        print("Error: JSON root must be an array.")
        return

    for item in data:
        if not isinstance(item, dict):
            print("Error: Each item must be a dictionary.")
            return

        name = item.get("name")
        price = item.get("price")
        quantity = item.get("quantity")

        if name is None or price is None or quantity is None:
            print("Error: Missing required keys in product data.")
            return

        try:
            total_value += float(price) * int(quantity)
        except (ValueError, TypeError):
            print("Error: Invalid numeric values for price or quantity.")
            return

    print(f"Total value of all products in stock: ${total_value:.2f}")

if __name__ == "__main__":
