def flatten_and_join(data, separator=None):
    """
    Flattens a nested list of strings and joins them with a separator.
    If the input is not a list, returns its string representation.
    Default separator is '\n'.
    """
    if not isinstance(data, list):
        return str(data)

    def flatten(nested_list):
        result = []
        for item in nested_list:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(str(item))
        return result

    flattened = flatten(data)
    return separator.join(flattened) if separator else '\n'.join(flattened)
```

