import sys

def derangements(n: int) -> int:
    # Use the recurrence: !n = (n-1) * (!(n-1) + !(n-2))
    # Base cases: !1 = 0, !0 = 1 (convention for recurrence)
    if n == 1:
        return 0
    if n == 0:
        return 1

    a, b = 1, 0  # !0, !1
    for i in range(2, n + 1):
        a, b = b, (i - 1) * (a + b)
    return b

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    print(derangements(n))

if __name__ == "__main__":
