class Matrix:
    def __init__(self, data):
        self.rows = len(data)
        self.cols = len(data[0])
        self.data = [row[:] for row in data]

    def add(self, other):
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions")
        return Matrix([[self.data[i][j] + other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def subtract(self, other):
        if self.rows != other.rows or self.cols != other.cols:
            raise ValueError("Matrices must have the same dimensions")
        return Matrix([[self.data[i][j] - other.data[i][j] for j in range(self.cols)] for i in range(self.rows)])

    def multiply(self, other):
        if self.cols != other.rows:
            raise ValueError("Number of columns in first matrix must equal number of rows in second")
        result_rows = self.rows
        result_cols = other.cols
        result = [[0 for _ in range(result_cols)] for _ in range(result_rows)]
        for i in range(result_rows):
            for j in range(result_cols):
                for k in range(self.cols):
                    result[i][j] += self.data[i][k] * other.data[k][j]
        return Matrix(result)

    def __str__(self):
        return '\n'.join(' '.join(map(str, row)) for row in self.data)
