def factorial(n):
    """Compute n! using recursion with memoization."""
    memo = {0: 1}

    def _factorial(k):
        if k in memo:
            return memo[k]
        if k < 0:
            raise ValueError("Input must be non-negative.")
        if k > 20:
            raise ValueError("Input must be <= 20.")
        memo[k] = k * _factorial(k - 1)
        return memo[k]

    if not isinstance(n, int) or n < 0 or n > 20:
        raise ValueError("Input must be an integer between 0 and 20.")

    return _factorial(n)


# Example usage:
