def first_missing_positive(arr):
    n = len(arr)
    # Use a set for O(1) lookup, but only care about numbers in [1, n]
    seen = set()
    for x in arr:
        if 1 <= x <= n:
            seen.add(x)

    # Check from 1 to n+1
    for i in range(1, n + 2):
        if i not in seen:
            return i
    return n + 1
```

