def fibonacci(n):
    """Compute the nth Fibonacci number using memoization."""
    memo = {0: 0, 1: 1}

    def fib(k):
        if k in memo:
            return memo[k]
        memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]

    if n < 0:
        raise ValueError("n must be non-negative")
    return fib(n)


