def is_valid_date(year, month, day):
    """Check if the date is valid, handling leap years."""
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False

    # Days per month (non-leap year)
    days_in_month = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Leap year check
    is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    if month == 2 and is_leap:
        if day > 29:
            return False
    elif month in [4, 6, 9, 11]:
        if day > 30:
            return False
    else:
        if day > 31:
            return False

    return True

def is_earlier_date(date1_str, date2_str):
    """
    Compare two date strings in 'YYYY-MM-DD' format.
    Returns True if date1 is strictly earlier than date2.
    Raises ValueError if format is invalid or dates are invalid.
    """
    import re

    # Validate format with regex
    pattern = r'^(\d{4})-(\d{2})-(\d{2})$'
    if not re.match(pattern, date1_str) or not re.match(pattern, date2_str):
        raise ValueError("Invalid date format. Expected YYYY-MM-DD.")

    # Parse dates
    y1, m1, d1 = map(int, date1_str.split('-'))
    y2, m2, d2 = int(date2_str.split('-')[0]), int(date2_str.split('-')[1]), int(date2_str.split('-')[2])

    # Validate dates
    if not is_valid_date(y1, m1, d1):
        raise ValueError(f"Invalid date: {date1_str}")
    if not is_valid_date(y2, m2, d2):
        raise ValueError(f"Invalid date: {date2_str}")

    # Compare lexicographically (safe since format is fixed and validated)
    if date1_str < date2_str:
        return True
    else:
        return False

# Example usage:
