def optimize_array(arr):
    if len(arr) <= 1:
        return arr[:]

    def partition(sub, low, high):
        pivot = sub[high]
        i = low - 1
        for j in range(low, high):
            if sub[j] <= pivot:
                i += 1
                sub[i], sub[j] = sub[j], sub[i]
        sub[i + 1], sub[high] = sub[high], sub[i + 1]
        return i + 1

    def quicksort_recursive(sub, low, high):
        if low < high:
            pi = partition(sub, low, high)
            quicksort_recursive(sub, low, pi - 1)
            quicksort_recursive(sub, pi + 1, high)

    # Create a copy to avoid modifying the original array
    result = arr[:]
    quicksort_recursive(result, 0, len(result) - 1)
    return result
```

