def isValid(s: str) -> bool:
    pairs = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()
        else:
            return False  # Should not happen based on constraints

    return not stack
```

