def encode_data(data: Any) -> Any:
    """
    Recursively encode string and integer values in a data structure (dict/list) into bytes.
    Other types are returned unchanged.
    """
    if isinstance(data, str):
        return data.encode('utf-8')
    elif isinstance(data, int):
        return str(data).encode('utf-8')
    elif isinstance(data, (dict, list)):
        if isinstance(data, dict):
            return {encode_data(k): encode_data(v) for k, v in data.items()}
        else:
            return [encode_data(item) for item in data]
