    - Four parts separated by dots.
    - Each part: 0-255, no leading zeros (except "0" itself).
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not (0 <= int(part) <= 255):
            return False

