def binary_search(a, v):
    left, right = 0, len(a) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2

        if a[mid] == v:
            result = mid
            right = mid - 1  # Look in the left half for the first occurrence
        elif a[mid] < v:
            left = mid + 1
        else:
            right = mid - 1

    return result
```

