def binary_search(a, v):
    left, right = 0, len(a) - 1
    while left <= right:
        mid = (left + right) // 2
        if a[mid] < v:
            left = mid + 1
        elif a[mid] > v:
            right = mid - 1
        else:
            # Move left to find the first occurrence
            right = mid - 1
    return left if left < len(a) and a[left] == v else -1
```

