def get_sorted_unique(lst):
    # Track seen numbers using a list and a boolean flag for each
    seen = [False] * 2001  # indices -1000 to 1000
    result = []

    for num in lst:
        idx = num + 1000  # shift to non-negative index
        if not seen[idx]:
            seen[idx] = True
            result.append(num)

    # Sort the result manually (bubble sort)
    n = len(result)
    for i in range(n):
        for j in range(0, n - i - 1):
            if result[j] > result[j + 1]:
                result[j], result[j + 1] = result[j + 1], result[j]

    return result
```

